import {WalkLocationController} from './walk-location.js';
import {NavigationController} from './navigation-controller.js';
import {ArrivalController} from './arrival-controller.js';
import {resolvePoiImage,bindImageFallbacks} from './poi-images.js';
import {controls,editor,settlementPage} from './walk-controls.js';
import {api} from './api.js';
import {translator} from './i18n.js';
import {escapeHTML as e,poiName,minutes,distance as formatDistance,walkingMetrics,remaining,hasCJK,walkSummary} from './lib.js';
import {icon,button,iconButton,imageSlot,skeleton,openingStatus,culturalBridge} from './components.js';
import {MapController} from './map-controller.js';

const root=document.querySelector('#app');
bindImageFallbacks(root);
const state={lang:localStorage.getItem('tracemate-language')||'en',screen:'home',data:null,content:null,trip:null,
  form:{mode:'plan_for_me',time:180,pace:'standard',zone:'wukang_fuxing_xujiahui',interests:['architecture','local_life'],places:[],start:'',text:'',query:''},
  selected:null,detail:null,tab:'overview',nearbyCategory:'CAFE',nearby:null,nearbyBusy:false,nearbyError:null,
  info:{},reality:null,realityBusy:false,realityKey:null,error:null,busy:false,entry:null,mobileView:'itinerary',galleryZone:'',modal:null,motionPaused:false,turnResult:null,chatText:"",editKind:"ADD_MUST_GO"};
if(!['en','zh'].includes(state.lang))state.lang='en';
let map=null,mapViewport=null,orbitFrame=0,nearbyRequest=0,realityRequest=0,itineraryScroll=0;
state.distanceUnit=localStorage.getItem('tracemate-distance-unit')==='mi'?'mi':'km';
const distance=value=>formatDistance(value,state.distanceUnit);
const t=key=>translator(state.lang)(key);
const pois=()=>state.data?.pois||[];
const getPoi=id=>pois().find(p=>p.id===id);
const name=id=>poiName(getPoi(id),state.lang);
const route=()=>state.trip?.active_route;
const active=()=>state.trip?.status==='ACTIVE';
const themeFor=id=>['stone','sage','clay','blue','amber'][Number(id?.replace('p','')||0)%5];
const arrivals=new ArrivalController({state,t,name,getPoi,photo,render,loadNearby,nearbyView:nearbyPanel,focus:id=>map?.focus(id),refreshRoute:()=>loadReality()});
const navigation=new NavigationController({state,t,name,getPoi,arrivals,render,distance,refreshReality:()=>loadReality(true),refreshMap:()=>{if(map)map.update(mapOptions());},fit:()=>map?.fit()});
const walkLocation=new WalkLocationController({state,navigation,arrivals,render,focus:()=>map?.focus('__user__'),t});
navigation.startReady=()=>walkLocation.ready();navigation.startStatus=()=>walkLocation.status();navigation.requestLocation=()=>{const p=state.userLocation;if(p&&Date.now()-p.timestamp<=30000)return navigation.setOrigin(p,{kind:'gps'});navigation.origin=null;walkLocation.retry();};
function photo(id,cls=''){return imageSlot(resolvePoiImage(id,{manifest:state.imageManifest,curated:state.content?.pois,poi:getPoi(id),lang:state.lang}),name(id),cls,`poi-${id}`);}
function announce(text){document.querySelector('#announcement').textContent=text;}
function navigate(screen){state.error=null;state.entry=null;state.detail=null;if(location.hash===`#${screen}`){state.screen=screen;render();}else location.hash=screen;window.scrollTo({top:0});}

function header(){return `<header class="site-header ${state.screen==='route'?'workspace-header':''}"><a class="wordmark" href="#home" aria-label="TraceMate · Home"><img src="/assets/brand.jpg" alt="">TraceMate<span class="brand-local">沪迹</span></a>${state.screen!=='home'?`<nav aria-label="${e(t('menu'))}"><a href="#explore" ${state.screen==='explore'?'aria-current="page"':''}>${e(t('explore'))}</a><a href="#plan" data-action="plan" ${state.screen==='plan'?'aria-current="page"':''}>${e(t('plan'))}</a>${state.trip?`<a href="#route" ${state.screen==='route'?'aria-current="page"':''}>${e(t('yourWalk'))}</a>`:''}</nav>`:''}<div class="header-right">${state.screen!=='home'?button(t('settings'),'settings','text'):''}<button class="language-switch" data-action="language" aria-label="${e(t('language'))}"><span class="${state.lang==='en'?'current':''}">EN</span><span class="slash">/</span><span class="${state.lang==='zh'?'current':''}">${state.lang==='en'?'ZH':'中文'}</span></button></div></header>`;}
function errorBanner(){return state.error?`<div class="error-banner" role="alert"><span>${e(t(state.error))}</span><button data-action="clear-error" aria-label="${e(t('close'))}">${icon('close')}</button></div>`:'';}
function footer(){return `<footer class="site-footer"><span class="wordmark">TraceMate${state.lang==='zh'?'<span>沪迹</span>':''}</span><p>${e(t('footer'))}</p><span>${e(t('footerCity'))} ↗</span></footer>`;}

function home(){const cards=state.content?.hero||[];return `<main id="main" class="landing">
 <section class="hero"><div class="hero-orbit" aria-hidden="true">${cards.map((slot,i)=>`<div class="orbit-card" data-orbit="${i}">${imageSlot(slot,t(slot.label),'',slot.id)}<span class="orbit-caption"><span>${String(i+1).padStart(2,'0')} / ${e(t(slot.label))}</span><span>↗</span></span></div>`).join('')}</div>
 <div class="hero-copy"><p class="eyebrow">${e(t('heroEyebrow'))}</p><h1><span>${e(t('heroOne'))}</span><span class="display-second">${e(t('heroTwo'))}</span></h1><p class="hero-description">${e(t('heroCopy')).replaceAll('\n','<br>')}</p><div class="hero-actions">${button(t('planCta'),'plan','primary hero-entry') }<a class="text-link" href="#explore">${e(t('exploreCta'))} ${icon('arrow')}</a></div></div>
 <div class="hero-foot"><div><span>${e(t('location'))}</span><small>${e(t('coordinates'))}</small></div><a class="scroll-cue" href="#how">${e(t('scroll'))}<span>↓</span></a><button class="motion-toggle" data-action="motion">${icon(state.motionPaused?'play':'pause')}<span>${e(t(state.motionPaused?'play':'pause'))}</span></button></div></section>
 <section id="how" class="editorial-section how-section"><div class="editorial-copy"><span class="eyebrow">01 / ${e(t('howEyebrow'))}</span><h2>${e(t('howTitle')).replaceAll('\n','<br>')}</h2><p>${e(t('howCopy'))}</p><ol class="how-steps">${['One','Two','Three'].map((n,i)=>`<li><span>0${i+1}</span><div><h3>${e(t(`how${n}`))}</h3><p>${e(t(`how${n}Copy`))}</p></div></li>`).join('')}</ol></div><div class="feature-composition">${imageSlot(state.content?.features?.walk,t('photoReserved'),'feature-image','feature-walk')}<div class="field-note"><span class="eyebrow">TRACEMATE / ${e(t('location'))}</span><span class="note-route" aria-hidden="true"><i>01</i><b></b><i>02</i><b></b><i>03</i></span><p>${e(t('footerCity'))}</p><span class="note-stamp">↗</span></div></div></section>
 <section class="editorial-section culture-section"><div class="culture-visual">${imageSlot(state.content?.features?.culture,t('photoReserved'),'feature-image','feature-culture')}<span class="culture-glyph" aria-hidden="true">↔</span></div><div class="editorial-copy"><span class="eyebrow">02 / ${e(t('cultureEyebrow'))}</span><h2>${e(t('cultureTitle')).replaceAll('\n','<br>')}</h2><p>${e(t('cultureCopy'))}</p><p class="culture-teaser">${e(state.content?.cultural_bridge?.landing?.[state.lang]||t('cultureReserved'))}</p><a class="text-link" href="#explore">${e(t('cultureButton'))}${icon('arrow')}</a></div></section>
 <section class="final-cta"><span class="eyebrow">TRACEMATE / SHANGHAI</span><h2>${e(t('finalTitle')).replaceAll('\n','<br>')}</h2>${button(t('planCta'),'plan')}</section>${footer()}</main>`;}

function chip(value,label,selected,action,extra=''){return `<button class="chip ${selected?'selected':''}" aria-pressed="${!!selected}" data-action="${action}" data-value="${e(value)}" ${extra}>${e(label)}</button>`;}
function modeSelector(){return `<div class="mode-selector" role="group" aria-label="${e(t('modeLabel'))}">${['plan_for_me','places_in_mind','surprise_me'].map((mode,i)=>`<button data-action="mode" data-value="${mode}" class="mode-option ${state.form.mode===mode?'selected':''}" aria-pressed="${state.form.mode===mode}"><span class="mode-number">0${i+1}</span><strong>${e(t(mode))}</strong><small>${e(t(`${mode}_desc`))}</small><span class="mode-check">${state.form.mode===mode?icon('check'):''}</span></button>`).join('')}</div>`;}
function zoneCards(){return `<div class="zone-grid">${state.data.zones.map(z=>`<button type="button" class="zone-card" data-action="choose-zone" data-value="${z.id}">${imageSlot(state.content?.zones?.[z.id]||{theme:'sage'},z[state.lang==='zh'?'name_zh':'name_en'],'zone-photo',`zone-${z.id}`)}<strong>${e(z[state.lang==='zh'?'name_zh':'name_en'])}</strong>${icon('arrow')}</button>`).join('')}</div>`;}
function placePicker(){const f=state.form,query=f.query.toLowerCase();return pois().filter(p=>p.zone_id===f.zone&&`${p.name_en} ${p.name_zh}`.toLowerCase().includes(query)).map(p=>`<button type="button" class="place-choice ${f.places.includes(p.id)?'selected':''}" data-action="place" data-value="${p.id}" aria-pressed="${f.places.includes(p.id)}">${photo(p.id,'picker-image')}<span><strong>${e(poiName(p,state.lang))}</strong><small>${e(p[state.lang==='zh'?'zone_zh':'zone_en'])}</small></span><span class="checkbox">${f.places.includes(p.id)?icon('check'):''}</span></button>`).join('');}
function selectedPlaces(){return `<div class="selected-places"><h3>${e(t('selectedPlaces'))} <span>${state.form.places.length}</span></h3><div class="chips">${state.form.places.map(pid=>chip(pid,`${name(pid)} ×`,true,'place')).join('')}</div></div>`;}
function setup(){const f=state.form,zone=state.data.zones.find(z=>z.id===f.zone);return `<main id="main" class="setup-page"><div class="setup-heading"><span class="eyebrow">${e(t('setupEyebrow'))}</span><h1>${e(t('setupTitle'))}</h1><p>${e(t('setupCopy'))}</p></div><p class="planning-guide">${e(t('planningGuide'))}</p>${modeSelector()}<div class="setup-layout"><form id="setup-form" class="setup-form"><div class="question-group-title">${e(t('requiredQuestions'))}<p>${e(t('requiredGuide'))}</p></div>
${f.mode!=='places_in_mind'?`<section class="form-section"><div class="section-heading"><span>01</span><h2>${e(t('time'))} <span class="requirement-label">${e(t('mustSelect'))}</span></h2></div><p class="question-hint">${e(t('timeGuide'))}</p><div class="chips time-chips">${[90,120,180,240].map(n=>chip(n,minutes(n,t),f.time===n,'time')).join('')}</div></section>`:''}
<section class="form-section"><div class="section-heading"><span>02</span><h2>${e(t(f.mode==='plan_for_me'?'interests':f.mode==='places_in_mind'&&!zone?'area':f.mode==='places_in_mind'?'choosePlaces':'area'))} <span class="requirement-label">${e(t('mustSelect'))}</span></h2></div><p class="question-hint">${e(t(f.mode==='plan_for_me'?'interestGuide':f.mode==='places_in_mind'?'placesGuide':'surpriseGuide'))}</p>
${f.mode==='plan_for_me'?`<div class="chips interest-chips">${Object.keys(state.data.taxonomy.interest_tags).map(tag=>chip(tag,t(tag),f.interests.includes(tag),'interest')).join('')}</div>`:f.mode==='places_in_mind'?(!zone?zoneCards():`<div class="chosen-zone"><strong>${e(zone[state.lang==='zh'?'name_zh':'name_en'])}</strong>${button(t('changeZone'),'change-zone','text')}</div><label class="search-input">${icon('search')}<input data-input="query" placeholder="${e(t('searchPlaces'))}" aria-label="${e(t('searchPlaces'))}" value="${e(f.query)}"></label><div class="place-picker" id="place-picker">${placePicker()}</div>${selectedPlaces()}`):`<label class="field-label">${e(t('area'))}<select data-input="zone"><option value="">${e(t('pickZone'))}</option>${state.data.zones.map(z=>`<option value="${z.id}" ${f.zone===z.id?'selected':''}>${e(z[state.lang==='zh'?'name_zh':'name_en'])}</option>`).join('')}</select></label>`}</section>
<div class="question-group-title optional-title">${e(t('optionalQuestions'))}<p>${e(t('optionalGuide'))}</p></div><section class="form-section"><div class="section-heading"><h2>${e(t('pace'))}</h2></div><p class="question-hint">${e(t('paceGuide'))}</p><div class="segmented">${['quick','standard','deep'].map(p=>chip(p,t(p),f.pace===p,'pace')).join('')}</div></section>
${f.mode==='plan_for_me'?`<section class="form-section compact"><p class="question-hint">${e(t('zoneGuide'))}</p><label class="field-label question-label">${e(t('area'))}<select data-input="zone"><option value="">${e(t('anyArea'))}</option>${state.data.zones.map(z=>`<option value="${z.id}" ${f.zone===z.id?'selected':''}>${e(z[state.lang==='zh'?'name_zh':'name_en'])}</option>`).join('')}</select></label></section>`:''}
${f.mode==='plan_for_me'&&state.data.capabilities.natural_language?`<details class="natural-input" ${f.text?'open':''}><summary>${e(t('noteLabel'))}</summary><p class="question-hint">${e(t('wordsGuide'))}</p><textarea data-input="text" aria-label="${e(t('noteLabel'))}" rows="3" placeholder="${e(t('notePlaceholder'))}">${e(f.text)}</textarea><p class="small muted">${e(t('naturalHint'))}</p></details>`:''}
<div class="form-footer"><p>${e(t('footerCity'))}</p><button class="button primary" type="submit">${e(t('generate'))}${icon('arrow')}</button></div></form></div></main>`;}

function generating(){return `<main id="main" class="generation-page" aria-busy="true"><div class="route-loader" aria-hidden="true"><svg viewBox="0 0 320 140"><path d="M25 110C65 110 40 35 100 35S180 120 220 85 240 30 290 30"/><circle cx="25" cy="110" r="7"/><circle cx="100" cy="35" r="7"/><circle cx="220" cy="85" r="7"/><circle cx="290" cy="30" r="7"/></svg></div><span class="eyebrow">${e(t('generationStage'))}</span><h1>${e(t('generationTitle')).replaceAll('\n','<br>')}</h1><p>${e(t('generationCopy'))}</p><span class="loading-line"></span><p class="small muted" role="status">${e(t('generationWait'))}</p></main>`;}
function entryState(){const entry=state.entry;const questions=entry.intent?.clarification_requests||[];return `<main id="main" class="result-page"><span class="eyebrow">TRACEMATE / ${e(t('plan'))}</span><h1>${e(t(entry.status.startsWith('needs_')?'clarification':'routeFailureTitle'))}</h1><p>${e(t(entry.status==='needs_route_quality_clarification'?'qualityQuestion':entry.status==='needs_clarification'?'setupCopy':'noRoute'))}</p>
 ${entry.status==='needs_route_quality_clarification'?`<div class="clarification-options">${entry.route_quality.options.map(o=>button(t(o.value)==o.value?`${t('addTheme')} ${t(o.value)}`:t(o.value),'quality','secondary',`data-value="${e(o.value)}"`)).join('')}</div>`:entry.status==='needs_clarification'?`<form id="clarify-form">${questions.map(q=>`<fieldset><legend>${e(t(({available_minutes:'time',interest_tags:'interests',must_go_poi_ids:'choosePlaces',start_location_text:'start'})[q.field]||'clarification'))}</legend>${q.options.map(o=>`<label class="clarification-choice"><input type="${q.input_type==='multi_choice'?'checkbox':'radio'}" name="${q.field}" value="${e(JSON.stringify(o.value))}" ${q.input_type==='multi_choice'?'':'required'}><span>${e(q.field==='must_go_poi_ids'?name(o.value):q.field==='available_minutes'?minutes(o.value,t):t(o.value))}</span></label>`).join('')}</fieldset>`).join('')}<button class="button primary">${e(t('continue'))}${icon('arrow')}</button></form>`:''}
 ${state.lang==='zh'&&entry.errors?.length?`<details class="original-note"><summary>${e(t('originalNote'))}</summary><p>${e(entry.errors.join(' '))}</p></details>`:''}<div>${button(t('adjust'),'back-setup','text')}</div></main>`;}

function zoneIntroductions(){return `<section class="zone-introductions">${state.data.zones.filter(z=>!state.galleryZone||state.galleryZone===z.id).map(z=>`<article><span class="eyebrow">${e(z.name_en)}</span><h2>${e(z[state.lang==='zh'?'name_zh':'name_en'])}</h2><p>${e(state.content?.zones?.[z.id]?.introduction?.[state.lang]||t('zoneIntroReserved'))}</p></article>`).join('')}</section>`;}
function gallery(){const filtered=pois().filter(p=>!state.galleryZone||p.zone_id===state.galleryZone);return `<main id="main" class="gallery-page"><div class="gallery-heading"><span class="eyebrow">${e(t('galleryEyebrow'))}</span><h1>${e(t('galleryTitle'))}</h1><p>${e(t('galleryCopy'))}</p></div><div class="chips gallery-filters">${chip('',t('browseAll'),!state.galleryZone,'gallery-zone')}${(state.data?.zones||[]).map(z=>chip(z.id,z[state.lang==='zh'?'name_zh':'name_en'],state.galleryZone===z.id,'gallery-zone')).join('')}</div>${zoneIntroductions()}<div class="place-grid">${filtered.map(p=>`<button class="gallery-place" data-action="gallery-poi" data-value="${p.id}">${photo(p.id,'gallery-image')}<span class="eyebrow">${e(p.category?.[state.lang==='zh'?'zh':'en']||'Shanghai')}</span><h2>${e(poiName(p,state.lang))}</h2><span class="gallery-meta">${e(p[state.lang==='zh'?'zone_zh':'zone_en'])}${icon('arrow')}</span></button>`).join('')}</div>${footer()}</main>`;}

function weatherContext(){const weather=state.reality?.weather;if(state.realityBusy)return `<span class="weather-context">${icon('sun')}${e(t('contextLoading'))}</span>`;if(!weather||weather.data_status==='UNAVAILABLE')return `<span class="weather-context muted">${icon('sun')}${e(t('weatherUnavailable'))}</span>`;let text=weather.weather_text||'';if(state.lang==='en'){text=text.includes('雪')?t('snow'):text.includes('雨')?t('rain'):text==='晴'?t('sunny'):text.includes('云')||text==='阴'?t('cloudy'):hasCJK(text)?t('conditions'):text;}
 return `<span class="weather-context" title="${e(weather.report_time||'')}">${icon('sun')}${weather.temperature_c??'—'}°C <span>· ${e(text)}</span></span>`;}
function routeWarnings(){const warnings=state.reality?.warnings||[];if(!warnings.length)return '';return `<details class="route-warnings"><summary><span class="warning-dot"></span>${e(t('routeWarning'))}<span>${warnings.length}</span></summary><ul>${warnings.map(w=>`<li>${w.poi_id?`<strong>${e(name(w.poi_id))}</strong>`:''}${e(t(w.code))}${w.details?.excess_minutes?` <span>+${minutes(w.details.excess_minutes,t)}</span>`:''}</li>`).join('')}</ul></details>`;}
function routeStop(stop,i){const visited=state.trip.visited_poi_ids.includes(stop.poi_id),skipped=state.trip.skipped_poi_ids.includes(stop.poi_id);const leg=route().walking_legs?.find(l=>l.to_poi_id===stop.poi_id);const selected=state.selected===stop.poi_id;return `${leg?`<div class="walking-segment">${icon('walk')}<span>${distance(leg.distance_m)} <span>·</span> ${minutes(leg.duration_s==null?null:leg.duration_s/60,t)}${leg.status!=='AVAILABLE'?` · ${e(t('approximate'))}`:''}</span></div>`:''}
 <article class="itinerary-stop ${selected?'selected':''} ${visited||skipped?'past':''}" data-stop="${stop.poi_id}"><button class="stop-button" data-action="poi" data-value="${stop.poi_id}" aria-pressed="${selected}"><span class="stop-number">${visited?icon('check'):String(i+1).padStart(2,'0')}</span><span class="stop-body"><span class="stop-category">${e(getPoi(stop.poi_id)?.category?.[state.lang==='zh'?'zh':'en']||'')}</span><strong>${e(name(stop.poi_id))}</strong><span class="stop-meta">${minutes(stop.estimated_stay_minutes,t)} <i>·</i> ${e(t(visited?'completed':skipped?'skipped':'visit'))}${stop.must_go?'<span class="must-go-dot">*</span>':''}</span></span><span class="stop-thumbnail">${photo(stop.poi_id)}</span></button></article>`;}

function workspace(){if(!state.trip)return setup();const m=walkingMetrics(route()),done=state.trip.status==='COMPLETED'||state.trip.status==='ABANDONED';if(done)return settlement();const zone=(state.data?.zones||[]).find(z=>z.id===route().selected_zone);const next=remaining(state.trip)[0];return `<main id="main" class="workspace mobile-${state.mobileView}"><section class="itinerary-panel" id="route-itinerary"><div class="route-heading"><div class="route-eyebrow"><span class="eyebrow">${e(t(active()?'activeWalk':'routeLabel'))}</span>${weatherContext()}</div><h1>${e(done?t('finishedTitle'):zone?.[state.lang==='zh'?'name_zh':'name_en']||t('routeTitle'))}</h1><p>${e(t(done?'finishedCopy':'routeDescription'))}</p><div class="route-metrics"><span><strong>${distance(m.metres)}</strong>${e(t('walking'))}</span><span><strong>${minutes(m.totalMinutes,t)}</strong>${e(t('totalTime'))}</span><span><strong>${route().ordered_pois.length}</strong>${e(t('stops'))}</span></div><span class="route-data-status">${m.live?icon('check'):''}${e(t(m.live?'liveWalking':'approximate'))}</span><div class="route-actions">${!done?iconButton('compass',t('checkRoute'),'reality'):''}</div>${routeWarnings()}</div>
 ${active()&&next?`<div class="active-stop"><span class="eyebrow">${e(t('currentStop'))}</span><h2>${e(name(next.poi_id))}</h2><div>${button(t('imHere'),'arrive-manual','primary')}</div></div>`:''}
 ${navigation.panel()}${arrivals.sidebar()}${active()?walkControls():''}<div class="itinerary-title"><h2>${e(t('itinerary'))}</h2><span>${route().ordered_pois.length} ${e(t('stops'))}</span></div><div class="itinerary-list">${route().ordered_pois.map(routeStop).join('')}</div><div class="itinerary-foot">${active()?button(t('stopWalk'),'end','text'):!done?button(t('regenerate'),'regenerate','text'):''}</div></section><div class="workspace-divider" role="separator" tabindex="0" aria-orientation="vertical" aria-label="${e(t('resizePanels'))}" aria-controls="route-itinerary route-map"></div><section class="map-panel" id="route-map" aria-label="${e(t('map'))}"></section><div class="mobile-view-switch" role="group">${chip('itinerary',t('itinerary'),state.mobileView==='itinerary','mobile-view')}${chip('map',t('map'),state.mobileView==='map','mobile-view')}</div></main>`;}

function nearbyList(){if(state.nearbyBusy)return `<div class="panel-loading" role="status">${skeleton()}<p>${e(t('nearbyLoading'))}</p></div>`;if(state.nearbyError||state.nearby?.status==='UNAVAILABLE')return `<div class="empty-state"><p>${e(t('nearbyError'))}</p>${button(t('retry'),'nearby-retry','secondary')}</div>`;const results=state.nearby?.results||[];return results.length?`<div class="nearby-list">${results.map(p=>`<article class="nearby-item ${state.selected===p.service_poi_id?'selected':''}" data-stop="${e(p.service_poi_id)}"><span class="nearby-symbol">${icon('compass')}</span><div><h3>${e(serviceName(p))}</h3><p>${e(t(p.primary_category))} · ${distance(p.distance_m)}</p>${openingStatus(p,t)}<div class="nearby-actions"><button class="text-link" data-action="nearby-map" data-value="${e(p.service_poi_id)}">${e(t('onMap'))} ↗</button><button class="button secondary" data-action="nav-directions" data-value="${e(p.service_poi_id)}">${e(t('directions'))} ↗</button></div>${p.address?`<details><summary>${e(t('details'))}</summary><p>${e(state.lang==='en'?(p.address_en||(!hasCJK(p.address)?p.address:t('addressEnglishUnavailable'))):p.address)}</p>${p.tel?`<p>${e(state.lang==='en'?p.tel.replace(/转/g,' ext. ').replace(/[\u3400-\u9fff]/gu,''):p.tel)}</p>`:''}</details>`:''}</div></article>`).join('')}</div>`:`<div class="empty-state"><span>↗</span><p>${e(t('nearbyEmpty').replace('{radius}',distance(800)))}</p></div>`;}
function detail(){if(!state.detail||state.screen==='route')return '';const pid=state.detail,poi=getPoi(pid);if(!poi)return '';const info=state.info[pid],stop=route()?.ordered_pois.find(s=>s.poi_id===pid);const summary=poi.summary?.[state.lang==='zh'?'summary_zh':'summary_en'];const original=false;return `<div class="detail-shade" data-action="close-detail"></div><aside class="poi-detail" role="dialog" aria-modal="true" aria-label="${e(poiName(poi,state.lang))}"><div class="detail-top"><span class="eyebrow">${e(t('location'))}</span>${iconButton('close',t('close'),'close-detail')}</div><div class="detail-heading"><span class="eyebrow">${e(poi.category?.[state.lang==='zh'?'zh':'en']||'')}</span><h2>${e(poiName(poi,state.lang))}</h2>${state.lang==='zh'?`<p>${e(poi.name_en)}</p>`:''}</div>${photo(pid,'detail-image')}<div class="detail-tabs" role="tablist">${['overview','story','nearby'].map(tab=>`<button role="tab" aria-selected="${state.tab===tab}" data-action="detail-tab" data-value="${tab}">${e(t(tab))}</button>`).join('')}</div><div class="detail-content" role="tabpanel">
 ${state.tab==='overview'?`<div class="detail-meta">${stop?`<span>${minutes(stop.estimated_stay_minutes,t)} ${e(t('visit'))}</span>`:''}${info?openingStatus(info,t):skeleton()}</div>${info?.opentime_today?`<p class="small muted">${e(state.lang==='en'&&hasCJK(info.opentime_today)?t('hoursUnknown'):info.opentime_today)}</p>`:''}<section class="place-introduction">${original?`<small class="muted">${e(t('originalChinese'))}</small>`:''}<p>${e(summary||original||t('summaryUnavailable'))}</p></section><button class="story-prompt" data-action="detail-tab" data-value="story"><span class="eyebrow">${e(t('cultureEyebrow'))}</span><span>${e(t('lookFor'))}${icon('arrow')}</span></button>${state.screen!=='route'?button(t(active()?'addCore':'chooseForWalk'),'choose-for-walk','primary',`data-value="${pid}"`):''}`:
 state.tab==='story'?culturalBridge(state.content?.cultural_bridge?.places?.[pid],state.lang,t):`<h3 class="nearby-title">${e(t('nearbyTitle'))}</h3><p class="muted small">${e(t('nearbyCopy'))}</p><div class="nearby-filters">${['CAFE','RESTAURANT','TEA_DRINK','DESSERT_ICE_CREAM','CONVENIENCE_STORE','RESTROOM','MALL'].map(c=>chip(c,t(c),state.nearbyCategory===c,'nearby-category')).join('')}</div>${nearbyList()}<p class="nearby-distance-note">${e(t('nearbyDistanceNote'))}</p>`}
 </div></aside>`;}
function modal(){if(!state.modal)return '';if(['settings','replace'].includes(state.modal.type))return extraModal();if(state.modal.type==='edit')return editDialog();const replan=state.modal.type==='replan';return `<dialog id="action-dialog" aria-labelledby="modal-title"><div class="dialog-top">${iconButton('close',t('close'),'close-modal')}</div><span class="eyebrow">TRACEMATE</span><h2 id="modal-title">${e(t(replan?'replanTitle':state.modal.type==='skip'?'skipConfirm':'endConfirm'))}</h2><p>${e(t(replan?'replanNotice':state.modal.type==='skip'?'skipCopy':'endCopy'))}</p>${replan?`<form id="replan-form"><label class="field-label">${e(t('remainingTime'))}<input name="minutes" type="number" min="1" max="${Math.ceil(state.trip.remaining_minutes)}" value="${Math.ceil(state.trip.remaining_minutes)}" required></label><label class="field-label">${e(t('pace'))}<select name="pace">${['quick','standard','deep'].map(p=>`<option value="${p}" ${state.trip.current_intent.travel_pace===p?'selected':''}>${e(t(p))}</option>`).join('')}</select></label><button class="button primary" type="submit">${e(t('replanCta'))}${icon('arrow')}</button></form>`:`<div class="dialog-actions">${button(t('cancel'),'close-modal','secondary')}${button(t(state.modal.type==='skip'?'confirmSkip':'confirmEnd'),'confirm-action')}</div>`}</dialog>`;}

function render(){navigation.sync();const oldCardId=document.querySelector('.arrival-card')?.dataset.eventId;const arrivalScroll=document.querySelector('.arrival-card')?.scrollTop||0;const detailScroll=document.querySelector('.poi-detail')?.scrollTop||0;const expanded=[...document.querySelectorAll('.arrived-history[open],.demo-controller[open],.route-warnings[open],.advanced-options[open],.original-route[open],.adjustment-history[open]')].map(el=>'.'+el.classList[0]);arrivals.sync();walkLocation.sync();recordExploration();const prior=document.activeElement;const focusAction=prior?.dataset?.action,focusValue=prior?.dataset?.value;const wasInDetail=!!prior?.closest('.poi-detail');itineraryScroll=document.querySelector('.itinerary-panel')?.scrollTop??itineraryScroll;const savedMapHost=map?.host;if(map){mapViewport=map.getViewport();if(state.screen!=='route'||state.busy&&!state.turnBusy||state.entry||['COMPLETED','ABANDONED'].includes(state.trip?.status)||map.lang!==state.lang){map.destroy();map=null;}else savedMapHost.remove();}cancelAnimationFrame(orbitFrame);document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.body.classList.toggle('has-detail',!!state.detail);document.body.classList.toggle('app-surface',state.screen!=='home');document.querySelector('.skip-link').textContent=state.lang==='en'?'Skip to content':'跳到正文';
 const content=state.busy&&!state.turnBusy?generating():state.entry?entryState():state.screen==='home'?home():state.screen==='explore'?gallery():state.screen==='route'?workspace():setup();
 root.innerHTML=header()+errorBanner()+content+detail()+arrivals.card()+(state.screen==='route'&&active()&&arrivals.mode==='DEMO'?'<div class="simulation-indicator" role="status">SIMULATION</div>':'')+modal();bind();for(const selector of expanded){const el=document.querySelector(selector);if(el)el.open=true;}const arrivalElement=document.querySelector('.arrival-card');if(arrivalElement&&oldCardId===arrivalElement.dataset.eventId)arrivalElement.scrollTop=arrivalScroll;else arrivalElement?.focus({preventScroll:true});if(wasInDetail&&document.querySelector('.poi-detail'))document.querySelector('.poi-detail').scrollTop=detailScroll;if(document.querySelector('.itinerary-panel'))document.querySelector('.itinerary-panel').scrollTop=itineraryScroll;if(state.screen==='home'&&!state.busy&&!state.entry)animateOrbit();
 const newMapHost=document.querySelector('#route-map');if(newMapHost){if(map){newMapHost.replaceWith(savedMapHost);map.update(mapOptions());}else if(newMapHost.clientWidth>0)map=new MapController(newMapHost,mapOptions());}
 const historyHost=document.querySelector('#route-map');if(historyHost){historyHost.querySelectorAll('.map-arrival-history,.map-guidance-ui,.map-location-tools').forEach(el=>el.remove());historyHost.insertAdjacentHTML('beforeend',arrivals.mapHistory()+navigation.mapPanel()+walkLocation.panel());historyHost.querySelector('.arrived-history').addEventListener('toggle',event=>arrivals.historyExpanded=event.target.open);historyHost.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>dispatch(el.dataset.action,el.dataset.value));}
 if(state.modal){const d=document.querySelector('#action-dialog');d.showModal();d.oncancel=()=>{state.modal=null;};}
 const restoreFocus=()=>{if(focusAction){const selector=`[data-action="${CSS.escape(focusAction)}"]${focusValue!==undefined?`[data-value="${CSS.escape(focusValue)}"]`:''}`;root.querySelector(selector)?.focus({preventScroll:true});}};if(state.detail&&!wasInDetail)document.querySelector('.poi-detail [data-action="close-detail"]')?.focus({preventScroll:true});else if(!state.modal&&!(arrivalElement&&oldCardId!==arrivalElement.dataset.eventId))restoreFocus();
}
function mapOptions(){return {stops:route().ordered_pois,legs:route().walking_legs,nearby:(state.nearby?.results||[]).map(p=>({...p,name:serviceName(p)})),catalogue:pois(),lang:state.lang,t,live:state.data.capabilities.live_world,jsKey:state.data.capabilities.map_js_key,entrance:arrivals.entranceMarker?{...arrivals.entranceMarker,label:t(arrivals.entranceMarker.labelKey)}:null,userLocation:state.userLocation,heading:navigation.heading(),guidance:navigation.guidance,pickPoint:walkLocation.demo,onPoint:p=>walkLocation.click(p),selected:state.selected,viewport:mapViewport,onSelect:selectPoi,onHover:highlight,onLocate:locate};}
function highlight(id){map?.highlight(id);document.querySelectorAll('[data-stop]').forEach(el=>el.classList.toggle('hovered',el.dataset.stop===id));}
function bind(){document.querySelector('#origin-query')?.addEventListener('input',event=>{navigation.query=event.target.value;});document.querySelector('#origin-search')?.addEventListener('submit',event=>{event.preventDefault();navigation.search();});bindExtras();bindWalkControls();root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',event=>{event.preventDefault();dispatch(el.dataset.action,el.dataset.value);}));root.querySelectorAll('[data-input]').forEach(el=>{const fn=()=>{state.form[el.dataset.input]=el.value;if(el.dataset.input==='zone'){state.form.start='';if(state.form.mode==='surprise_me'){render();return;}}if(el.dataset.input==='query'){document.querySelector('#place-picker').innerHTML=placePicker();document.querySelectorAll('#place-picker [data-action]').forEach(b=>b.onclick=()=>dispatch('place',b.dataset.value));}};el.addEventListener(el.tagName==='SELECT'?'change':'input',fn);});
 root.querySelectorAll('.nearby-item').forEach(el=>{el.onmouseenter=()=>highlight(el.dataset.stop);el.onmouseleave=()=>highlight(null);});root.querySelectorAll('.stop-button').forEach(el=>{el.onmouseenter=el.onfocus=()=>highlight(el.dataset.value);el.onmouseleave=el.onblur=()=>highlight(null);});
 document.querySelector('#setup-form')?.addEventListener('submit',event=>{event.preventDefault();generate();});
 document.querySelector('#clarify-form')?.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target),answers={};for(const q of state.entry.intent.clarification_requests){const values=data.getAll(q.field).map(v=>JSON.parse(v));if(values.length)answers[q.field]=q.input_type==='multi_choice'?values:values[0];}runGeneration(()=>api.clarify({answers}));});
 document.querySelector('#replan-form')?.addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.target);act('replan',{delta:{remaining_minutes:Number(form.get('minutes')),pace:form.get('pace')}});});
}
async function dispatch(action,value){if(action==='nav-demo')return walkLocation.toggleDemo();if(action==='gps-retry')return walkLocation.retry();if(action.startsWith('nav-'))return navigation.action(action,value);if(action.startsWith('arrival-')||action.startsWith('demo-')||['arrive-manual','gps-retry'].includes(action)){await arrivals.action(action,value);return;}switch(action){
 case 'language':state.lang=state.lang==='en'?'zh':'en';localStorage.setItem('tracemate-language',state.lang);render();return;
 case 'plan':navigate('plan');return;
 case 'settings':state.modal={type:'settings'};render();return;
 case 'replace-walk':{const body=state.modal.body;state.modal=null;await runGeneration(()=>api.generate(body));return;}
 case 'motion':state.motionPaused=!state.motionPaused;render();return;
 case 'mode':if(state.form.mode!==value){state.form.zone=value==='plan_for_me'?'wukang_fuxing_xujiahui':'';state.form.places=[];state.form.start='';state.form.query='';}state.form.mode=value;state.error=null;render();return;
 case 'time':state.form.time=Number(value);render();return;
 case 'pace':state.form.pace=value;render();return;
 case 'interest':state.form.interests=state.form.interests.includes(value)?state.form.interests.filter(v=>v!==value):[...state.form.interests,value];render();return;
 case 'choose-zone':state.form.zone=value;state.form.places=[];state.form.query='';render();return;
 case 'change-zone':state.form.zone='';state.form.places=[];render();return;
 case 'edit-stops':state.modal={type:'edit'};render();return;
 case 'turn-answer':sendTurn({text:value});return;
 case 'place':{const scroll=document.querySelector('#place-picker')?.scrollTop||0,win=scrollY;state.form.places=state.form.places.includes(value)?state.form.places.filter(v=>v!==value):[...state.form.places,value];render();if(document.querySelector('#place-picker'))document.querySelector('#place-picker').scrollTop=scroll;window.scrollTo(0,win);return;}
 case 'gallery-zone':state.galleryZone=value;render();return;
 case 'gallery-poi':selectPoi(value);return;
 case 'poi':selectPoi(value);return;
 case 'close-detail':{const old=state.detail;state.detail=null;render();window.scrollTo(0,state.galleryScroll||0);document.querySelector(`[data-action="gallery-poi"][data-value="${old}"]`)?.focus({preventScroll:true});return;}
 case 'detail-tab':state.tab=value;render();if(value==='nearby')loadNearby();return;
 case 'nearby-category':state.nearbyCategory=value;loadNearby();return;
 case 'nearby-retry':loadNearby();return;
 case 'nearby-map':if(!['PLANNED','ACTIVE'].includes(state.trip?.status)){state.error='planForGuidance';render();return;}state.selected=value;state.detail=null;state.mobileView='map';navigate('route');render();map?.focus(value);return;
 case 'choose-for-walk':if(active()){state.detail=null;navigate('route');sendTurn({kind:'ADD_MUST_GO',targets:[value]});return;}state.form.mode='places_in_mind';state.form.places=[value];state.form.zone=getPoi(value).zone_id;navigate('plan');return;
 case 'mobile-view':state.mobileView=value;render();return;
 case 'back-setup':state.entry=null;state.error=null;render();return;
 case 'quality':runGeneration(()=>api.clarify({answer:value}));return;
 case 'clear-error':state.error=null;render();return;
 case 'start':if(!walkLocation.ready()){navigation.error=null;render();const note=document.querySelector('.start-location-note');note?.scrollIntoView({block:'nearest'});note?.animate([{opacity:1},{opacity:.3},{opacity:1}],{duration:600,iterations:2});return;}navigation.open=false;navigation.guidance=null;navigation.epoch++;navigation.pickPoint=false;act('start');return;
 case 'complete':act('complete',{poi_id:value});return;
 case 'skip':state.modal={type:'skip',poi:value};render();return;
 case 'end':state.modal={type:'end'};render();return;
 case 'quick-edit':state.editKind=value;state.modal={type:'edit'};render();return;
 case 'edit-kind':state.editKind=value;render();return;
 case 'confirm-action':{const m=state.modal;act(m.type==='skip'?'skip':'abandon',{poi_id:m.poi});return;}
 case 'close-modal':state.modal=null;render();return;
 case 'adjust':if(active()){state.modal={type:'replan'};render();}else navigate('plan');return;
 case 'regenerate':generate();return;
 case 'reality':loadReality(true);return;
 case 'retry-bootstrap':boot();return;
}}
function selectPoi(id){if(id==='__entrance__'){map?.focus(id);return;}state.selected=id;if(state.screen==='route'){render();map?.focus(id);return;}if(!state.detail)state.galleryScroll=scrollY;if(id.startsWith('amap:')){state.detail=state.nearbyOrigin;state.tab='nearby';render();map?.focus(id);return;}const changed=state.detail!==id;state.detail=id;if(changed){state.tab='overview';state.nearby=null;nearbyRequest++;}render();map?.focus(id);const row=document.querySelector(`[data-stop="${id}"]`),panel=document.querySelector('.itinerary-panel');if(row&&panel)panel.scrollTop=Math.max(0,row.offsetTop-panel.clientHeight/3);if(!state.info[id]||Date.now()-(state.info[id]._loadedAt||0)>60000)api.poi(id).then(info=>{state.info[id]={...info,_loadedAt:Date.now()};if(state.detail===id)render();}).catch(()=>{state.info[id]={open_status:'UNKNOWN'};if(state.detail===id)render();});}
async function generate(){if(state.busy)return;const f=state.form,text=f.mode==='plan_for_me'?f.text.trim():'';if(!text&&f.mode==='plan_for_me'&&!f.interests.length){state.error='chooseInterest';render();return;}if(f.mode==='places_in_mind'&&!f.places.length){state.error='chooseMust';render();return;}if(f.mode==='surprise_me'&&!f.zone){state.error='pickZone';render();return;}
 const intent={route_mode:f.mode,available_minutes:f.mode==='places_in_mind'?null:f.time,travel_pace:f.pace,preferred_zone:f.zone||null,interest_tags:f.mode==='plan_for_me'?f.interests:[],must_go_poi_ids:f.mode==='places_in_mind'?f.places:[]};
 if(f.mode==='surprise_me')intent.surprise_seed=Math.floor(Math.random()*1000000);
 const body=text?{text,intent}:{intent};if(active()){state.modal={type:'replace',body:{...body,replace_active:true,expected_trip_id:state.trip.trip_id,expected_revision:state.trip.state_revision}};render();return;}await runGeneration(()=>api.generate(body));}
async function runGeneration(call){state.busy=true;state.error=null;state.entry=null;state.detail=null;render();try{const result=await call();state.busy=false;if(result.entry?.status==='success'){state.trip=result.trip;state.turnResult=null;state.chatText='';state.selected=null;mapViewport=null;state.reality=null;state.realityKey=null;state.mobileView='itinerary';navigate('route');loadReality();}else{state.entry=result.entry;render();}}catch(error){state.busy=false;state.error=error.code||'server_error';render();}announce(state.error?t(state.error):t('yourWalk'));}
async function act(action,extra={}){if(state.busy)return;const revision=state.trip.state_revision;state.modal=null;state.busy=true;state.error=null;render();try{const result=await api.action({action,revision,...extra});state.trip=result.trip;if(result.turn)state.turnResult=result.turn;state.busy=false;if(result.replan&&!['success','no_change'].includes(result.replan.status)&&!result.replan.committed)state.error='replanFailed';state.realityKey=null;render();loadReality();}catch(error){state.busy=false;state.error=error.code||'server_error';if(error.code==='stale_state_conflict'){const data=await api.bootstrap();state.trip=data.trip;}render();}}
async function loadReality(force=false){if(!state.trip)return;const key=`${state.trip.trip_id}:${state.trip.state_revision}`;if(!force&&state.realityKey===key)return;state.realityKey=key;const token=++realityRequest;state.realityBusy=true;if(state.screen==='route'&&!state.busy)render();try{const result=await api.reality(state.gps?{current_location:state.gps}:{});if(token!==realityRequest)return;state.reality=result;const point=result.weather?.resolved_location?.location;if(state.locatePending&&point?.coordinate_system==='GCJ02'){if(point.lat>=30&&point.lat<=32&&point.lng>=120&&point.lng<=123)state.userLocation={...point,...state.gpsMeta};else state.error='locationOutside';}}catch{if(token!==realityRequest)return;state.reality=null;state.error='contextError';}state.realityBusy=false;if(state.screen==='route'&&!state.busy)render();if(state.locatePending&&state.userLocation)map?.focus('__user__');state.locatePending=false;}
async function loadNearby(){const pid=state.screen==='route'?arrivals.record?.core_poi_id:state.detail;if(!pid)return;state.nearbyOrigin=pid;const token=++nearbyRequest;state.nearbyBusy=true;state.nearby=null;state.nearbyError=null;render();try{const data=await api.nearby({...((state.screen==='route')?arrivals.nearbyOrigin():{poi_id:pid}),categories:[state.nearbyCategory],lang:state.lang});if(token!==nearbyRequest||(state.screen==='route'?arrivals.record?.core_poi_id:state.detail)!==pid)return;state.nearby=data;}catch{if(token!==nearbyRequest)return;state.nearbyError=true;}state.nearbyBusy=false;if((state.screen==='route'?arrivals.record?.core_poi_id:state.detail)===pid)render();}
function locate(){if(state.userLocation&&Date.now()-state.userLocation.timestamp<=30000){map?.focus('__user__');return;}walkLocation.retry();}

function animateOrbit(){const hero=document.querySelector('.hero'),cards=[...document.querySelectorAll('[data-orbit]')];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const start=performance.now();function frame(time){const width=hero.clientWidth,height=hero.clientHeight,small=width<700;const elapsed=(state.motionPaused||reduced?0:(time-start)/110000)*Math.PI*2;cards.forEach((card,i)=>{const angle=i/cards.length*Math.PI*2+elapsed-Math.PI/2;const x=Math.cos(angle)*width*(small?.53:.46),y=Math.sin(angle)*height*(small?.40:.365);const rotate=Math.sin(angle*1.5+i)*7;card.style.transform=`translate(${width/2+x}px,${height/2+y-20}px) translate(-50%,-50%) rotate(${rotate}deg)`;});if(!state.motionPaused&&!reduced&&state.screen==='home')orbitFrame=requestAnimationFrame(frame);}frame(start);}

document.addEventListener('keydown',event=>{if(event.key==='Escape'&&state.detail){dispatch('close-detail');}else if(event.key==='Escape'&&arrivals.record&&!state.modal){arrivals.dismiss();}if(event.key==='Tab'&&state.detail){const panel=document.querySelector('.poi-detail'),items=[...panel.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"],summary')].filter(el=>!el.disabled&&el.getClientRects().length);if(event.shiftKey&&document.activeElement===items[0]){event.preventDefault();items.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===items.at(-1)){event.preventDefault();items[0]?.focus();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(page==='how'){document.querySelector('#how')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}state.screen=['home','plan','explore','route'].includes(page)?page:'home';state.detail=null;state.entry=null;state.error=null;render();if(state.screen==='route'&&state.trip)loadReality();});

function serviceName(p){if(state.lang==='zh')return p.name;const value=p.name_en||p.name;if(!hasCJK(value))return value;const latin=value.replace(/[\u3400-\u9fff]+/gu,' ').replace(/[（）]/g,' ').trim();return latin&&/[a-z]/i.test(latin)?latin:`${t(p.primary_category)} · ${t('nameEnglishUnavailable')}`;}
function exploredIds(){try{const a=JSON.parse(localStorage.getItem('tracemate-explored')||'[]');return Array.isArray(a)?a.filter(id=>pois().some(p=>p.id===id)):[];}catch{return [];}}
function recordExploration(){if(!state.trip||!state.data)return;try{localStorage.setItem('tracemate-explored',JSON.stringify([...new Set([...exploredIds(),...state.trip.visited_poi_ids])].filter(id=>getPoi(id))));}catch{}}
function settlement(){return settlementPage({trip:state.trip,t,explored:exploredIds()})+arrivals.sidebar();}
function walkControls(){return controls({state,t,name});}
function editDialog(){return editor({state,t,pois:pois(),name});}
function bindWalkControls(){
 document.querySelector('#walk-message')?.addEventListener('input',event=>state.chatText=event.target.value);
 document.querySelector('#walk-chat')?.addEventListener('submit',event=>{event.preventDefault();if(state.chatText.trim())sendTurn({text:state.chatText.trim()});});
 document.querySelector('#edit-kind')?.addEventListener('change',event=>{state.editKind=event.target.value;render();});
 document.querySelector('#edit-route-form')?.addEventListener('submit',event=>{event.preventDefault();const f=new FormData(event.target),body={kind:f.get('kind')};if(f.has('target'))body.targets=[f.get('target')];if(f.has('reference'))body.references=[f.get('reference')];if(f.has('minutes'))body.minutes=Number(f.get('minutes'));if(f.has('pace'))body.pace=f.get('pace');if(f.has('tag'))body.tags=[f.get('tag')];if(f.has('count'))body.count=Number(f.get('count'));if(f.has('goal'))body.goal=f.get('goal');sendTurn(body);});
}
async function sendTurn(body){if(state.busy)return;const requestTrip=state.trip.trip_id;state.modal=null;state.turnBusy=true;state.busy=true;state.error=null;render();try{const result=await api.turn({revision:state.trip.state_revision,...body});if(state.trip.trip_id!==requestTrip){state.turnBusy=false;state.busy=false;render();return;}state.turnBusy=false;state.trip=result.trip;state.turnResult=result.turn;if(['APPLIED','PARTIALLY_APPLIED'].includes(result.turn.change_summary?.execution_status))state.chatText='';state.realityKey=null;state.busy=false;mapViewport=null;render();loadReality();}catch(error){state.turnBusy=false;state.busy=false;state.error=error.code||'server_error';if(error.code==='stale_state_conflict')state.trip=(await api.bootstrap()).trip;render();}}

async function boot(){try{const [data,content,images]=await Promise.all([api.bootstrap(),api.content(),fetch('/api/poi-images').then(r=>r.ok?r.json():null).catch(()=>null)]);state.imageManifest=images;state.data=data;state.content=content;state.trip=data.trip;const page=location.hash.slice(1);state.screen=['home','plan','explore','route'].includes(page)?page:'home';state.error=null;render();if(state.screen==='route'&&state.trip)loadReality();}catch{root.innerHTML=header()+`<main id="main" class="result-page"><h1>${e(t('errorTitle'))}</h1><p>${e(t('networkError'))}</p>${button(t('retry'),'retry-bootstrap')}</main>`;bind();}}
boot();

function extraModal(){const settings=state.modal.type==='settings';return `<dialog id="action-dialog" aria-labelledby="modal-title"><div class="dialog-top">${iconButton('close',t('close'),'close-modal')}</div><h2 id="modal-title">${e(t(settings?'settings':'replaceTitle'))}</h2>${settings?`<label class="field-label">${e(t('distanceUnit'))}<select id="distance-unit"><option value="km" ${state.distanceUnit==='km'?'selected':''}>${e(t('kilometres'))}</option><option value="mi" ${state.distanceUnit==='mi'?'selected':''}>${e(t('miles'))}</option></select></label>`:`<p>${e(t('replaceCopy'))}</p><div class="dialog-actions">${button(t('cancel'),'close-modal','secondary')}${button(t('replaceWalk'),'replace-walk')}</div>`}</dialog>`;}
function bindExtras(){
 document.querySelector('#walk-action-picker')?.addEventListener('change',event=>{if(!event.target.value)return;state.editKind=event.target.value;state.modal={type:'edit'};render();});
 document.querySelector('#distance-unit')?.addEventListener('change',event=>{state.distanceUnit=event.target.value;localStorage.setItem('tracemate-distance-unit',state.distanceUnit);render();document.querySelector('#distance-unit')?.focus();});
 const divider=document.querySelector('.workspace-divider'),workspace=document.querySelector('.workspace');if(!divider)return;
 const saved=Number(localStorage.getItem('tracemate-panel-ratio'));let ratio=Number.isFinite(saved)&&saved>=25&&saved<=70?saved:40;
 const update=value=>{ratio=Math.max(25,Math.min(70,value));workspace.style.setProperty('--panel-ratio',ratio+'%');divider.setAttribute('aria-valuenow',String(Math.round(ratio)));divider.setAttribute('aria-valuemin','25');divider.setAttribute('aria-valuemax','70');map?.map?.resize?.();};update(ratio);
 const save=()=>{localStorage.setItem('tracemate-panel-ratio',String(ratio));window.dispatchEvent(new Event('resize'));};
 divider.onpointerdown=event=>{if(event.button!==0)return;event.preventDefault();divider.setPointerCapture(event.pointerId);workspace.classList.add('resizing');};
 divider.onpointermove=event=>{if(!divider.hasPointerCapture(event.pointerId))return;const box=workspace.getBoundingClientRect();update((event.clientX-box.left)/box.width*100);};
 divider.onpointerup=divider.onpointercancel=event=>{if(divider.hasPointerCapture(event.pointerId))divider.releasePointerCapture(event.pointerId);workspace.classList.remove('resizing');save();};
 divider.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();update(event.key==='Home'?25:event.key==='End'?70:ratio+(event.key==='ArrowLeft'?-2:2));save();};
}

function nearbyPanel(){return `<h3 class="nearby-title">${e(t('nearbyTitle'))}</h3><div class="nearby-filters">${['CAFE','RESTAURANT','TEA_DRINK','DESSERT_ICE_CREAM','CONVENIENCE_STORE','RESTROOM','MALL'].map(c=>chip(c,t(c),state.nearbyCategory===c,'nearby-category')).join('')}</div>${nearbyList()}<p class="nearby-distance-note">${e(t('nearbyDistanceNote'))}</p>`;}

window.addEventListener('pagehide',()=>{navigation.cancelGps?.();walkLocation.stop();navigation.headingTracker.stop();clearTimeout(navigation.locationExpiry);arrivals.browser.stop();});
